#!/usr/bin/env python3
"""
System Configuration File Monitor

This script periodically scans important system configuration files
for modifications and reports any changes detected.
"""

import os
import sys
import time
import hashlib
import json
import logging
from datetime import datetime
from typing import Dict, List, Set
from dataclasses import dataclass

def get_default_config_files() -> List[str]:
    """Return a list of common system configuration files to monitor."""
    return [
        "/etc/passwd",
        "/etc/group", 
        "/etc/shadow",
        "/etc/gshadow",
        "/etc/ssh/sshd_config",
        "/etc/hosts",
        "/etc/hostname",
        "/etc/resolv.conf",
        "/etc/fstab",
        "/etc/crontab",
        "/etc/sysctl.conf",
        "/etc/security/limits.conf",
        "/etc/pam.d/common-auth",
        "/etc/pam.d/common-account",
        "/etc/pam.d/common-session",
        "/etc/pam.d/common-password"
    ]

def file_exists_safely(filepath: str) -> bool:
    """Check if a file exists and is accessible without raising exceptions."""
    try:
        return os.path.isfile(filepath) and os.access(filepath, os.R_OK)
    except (OSError, IOError):
        return False

def calculate_file_hash(filepath: str, algorithm: str = 'sha256') -> str:
    """Calculate the hash of a file's contents."""
    if not file_exists_safely(filepath):
        return ""

    hash_obj = hashlib.new(algorithm)
    try:
        with open(filepath, 'rb') as f:
            # Read in chunks to handle large files efficiently
            for chunk in iter(lambda: f.read(4096), b""):
                hash_obj.update(chunk)
        return hash_obj.hexdigest()
    except (OSError, IOError):
        return ""

def load_previous_hashes(state_file: str) -> Dict[str, str]:
    """Load previously stored file hashes from state file."""
    if not file_exists_safely(state_file):
        return {}

    try:
        with open(state_file, 'r') as f:
            data = json.load(f)
            # Ensure we have the right structure
            if isinstance(data, dict):
                return data
            else:
                return {}
    except (json.JSONDecodeError, OSError, IOError):
        return {}

def save_current_hashes(hashes: Dict[str, str], state_file: str) -> bool:
    """Save current file hashes to state file."""
    try:
        # Ensure directory exists
        os.makedirs(os.path.dirname(state_file), exist_ok=True)

        with open(state_file, 'w') as f:
            json.dump(hashes, f, indent=2)
        return True
    except (OSError, IOError):
        return False

def scan_config_files(file_list: List[str]) -> Dict[str, str]:
    """Scan the specified configuration files and return their hashes."""
    results = {}

    for filepath in file_list:
        if file_exists_safely(filepath):
            file_hash = calculate_file_hash(filepath)
            if file_hash:  # Only include files we could successfully read
                results[filepath] = file_hash

    return results

def find_modified_files(current: Dict[str, str], previous: Dict[str, str]) -> Dict[str, str]:
    """Compare current and previous file hashes to find modifications."""
    modified = {}

    # Check for modified or new files
    for filepath, current_hash in current.items():
        previous_hash = previous.get(filepath)
        if previous_hash is None:
            modified[filepath] = "new"
        elif previous_hash != current_hash:
            modified[filepath] = "modified"

    # Check for deleted files
    for filepath in previous.keys():
        if filepath not in current:
            modified[filepath] = "deleted"

    return modified

def setup_logging(log_file: str = None):
    """Set up logging for the application."""
    log_format = '%(asctime)s - %(levelname)s - %(message)s'

    if log_file:
        logging.basicConfig(
            level=logging.INFO,
            format=log_format,
            handlers=[
                logging.FileHandler(log_file),
                logging.StreamHandler(sys.stdout)
            ]
        )
    else:
        logging.basicConfig(
            level=logging.INFO,
            format=log_format
        )

def main():
    """Main function to run the configuration file monitoring."""
    # Configuration
    STATE_FILE = "/root/.openclaw/workspace/.config_monitor_state.json"
    LOG_FILE = "/root/.openclaw/workspace/config_monitor.log"
    SCAN_INTERVAL = 300  # 5 minutes in seconds

    # Set up logging
    setup_logging(LOG_FILE)

    logging.info("Starting system configuration file monitor")

    # Get files to monitor
    config_files = get_default_config_files()
    logging.info(f"Monitoring {len(config_files)} configuration files")

    while True:
        try:
            # Load previous state
            previous_hashes = load_previous_hashes(STATE_FILE)

            # Scan current files
            current_hashes = scan_config_files(config_files)

            # Find modifications
            modified_files = find_modified_files(current_hashes, previous_hashes)

            # Report findings
            if modified_files:
                logging.warning(f"Detected {len(modified_files)} file change(s):")

                for filepath, change_type in modified_files.items():
                    status_msg = f"{change_type}: {filepath}"
                    logging.warning(status_msg)

                    # Additional details for modified files
                    if change_type == "modified":
                        old_hash = previous_hashes.get(filepath, "unknown")
                        new_hash = current_hashes.get(filepath, "unknown")
                        logging.info(f"  Hash changed from {old_hash[:8]}... to {new_hash[:8]}...")

            # Save current state for next comparison
            if save_current_hashes(current_hashes, STATE_FILE):
                logging.debug("Successfully saved current file state")
            else:
                logging.error("Failed to save current file state")

            # Wait before next scan
            time.sleep(SCAN_INTERVAL)

        except KeyboardInterrupt:
            logging.info("Monitor stopped by user")
            break
        except Exception as e:
            logging.error(f"Unexpected error during monitoring: {str(e)}")
            time.sleep(SCAN_INTERVAL)  # Continue after error

if __name__ == "__main__":
    main()
